        // =====================================================================
        // YANGI (23-bosqich):
        //  1) Qatlamlar belgisi (SVG)  2) Tizimning oq oynalari o'rniga to'q tanlash oynalari
        //  3) Xodim/lavozimni aqlli tanlash  4) Akt sanalari  5) Ehtiyot qismlar bo'limi
        // =====================================================================
        var LYR_SVG = '<svg class="lyr-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linejoin="round" stroke-linecap="round"><path d="M12 3 2.5 8 12 13l9.5-5Z"/><path d="m2.5 12.5 9.5 5 9.5-5"/><path d="m2.5 17 9.5 5 9.5-5"/></svg>';
        var LYR_SVG_S = LYR_SVG.replace('class="lyr-ico"', 'class="lyr-ico-s"');

        // ---------- 2) To'q uslubdagi tanlash ro'yxati (barcha <select> uchun) ----------
        const PK = { sel: null };
        function pkClose() { ['pkSel', 'pkDate'].forEach(id => { const e = $id(id); if (e) e.classList.add('hidden'); }); PK.sel = null; PK.date = null; }
        function pkLabelFor(el) {
            const g = el.closest('.form-group, .nd-f, .hr-f, .pk-field'); const l = g ? g.querySelector('label, .field-label') : null;
            return l ? l.innerText.replace(/[:：]\s*$/, '').trim() : (el.getAttribute('aria-label') || 'Tanlang');
        }
        function pkOpenSelect(sel) {
            if (!sel || sel.disabled) return;
            PK.sel = sel;
            const opts = [];
            Array.from(sel.children).forEach(ch => {
                if (ch.tagName === 'OPTGROUP') { opts.push({ g: ch.label }); Array.from(ch.children).forEach(o => opts.push({ v: o.value, t: o.text, d: o.disabled })); }
                else if (ch.tagName === 'OPTION') opts.push({ v: ch.value, t: ch.text, d: ch.disabled });
            });
            PK.opts = opts;
            const many = opts.filter(o => !o.g).length > 9;
            $id('pkSelBox').innerHTML = `<div class="pk-h"><b>${escapeHtml(pkLabelFor(sel))}</b><span onclick="pkClose()">✕</span></div>` +
                (many ? `<input class="pk-q" id="pkSelQ" placeholder="🔍 Qidirish..." autocomplete="off" oninput="pkRenderSel()">` : '') + `<div class="pk-list" id="pkSelList"></div>`;
            pkRenderSel();
            $id('pkSel').classList.remove('hidden');
            const on = $id('pkSelList').querySelector('.pk-o.on'); if (on) on.scrollIntoView({ block: 'center' });
        }
        function pkRenderSel() {
            const q = aiNorm((($id('pkSelQ') || {}).value) || '').trim(), sel = PK.sel; if (!sel) return;
            let h = '', lastG = null;
            PK.opts.forEach((o, i) => {
                if (o.g !== undefined) { lastG = o.g; return; }
                if (q && !aiNorm(o.t).includes(q)) return;
                if (lastG !== null) { h += `<div class="pk-g">${escapeHtml(lastG)}</div>`; lastG = null; }
                h += `<div class="pk-o${o.v === sel.value ? ' on' : ''}${o.d ? ' dis' : ''}" onclick="pkPick(${i})"><span class="pk-t">${escapeHtml(o.t)}</span></div>`;
            });
            $id('pkSelList').innerHTML = h || '<div class="pk-o dis">Topilmadi</div>';
        }
        function pkPick(i) {
            const o = PK.opts[i], sel = PK.sel; if (!o || o.d || !sel) return;
            const ch = sel.value !== o.v; sel.value = o.v; pkClose();
            if (ch) { sel.dispatchEvent(new Event('input', { bubbles: true })); sel.dispatchEvent(new Event('change', { bubbles: true })); }
        }
        // ---------- To'q kalendar (barcha <input type="date"> uchun) ----------
        const OYLAR = ['Yanvar', 'Fevral', 'Mart', 'Aprel', 'May', 'Iyun', 'Iyul', 'Avgust', 'Sentyabr', 'Oktyabr', 'Noyabr', 'Dekabr'];
        function pkOpenDate(inp) {
            if (!inp || inp.disabled || inp.readOnly) return;
            const v = inp.value && /^\d{4}-\d{2}-\d{2}$/.test(inp.value) ? inp.value : todayISO();
            PK.date = { inp: inp, y: +v.slice(0, 4), m: +v.slice(5, 7) - 1, mode: 'd' };
            pkRenderDate(); $id('pkDate').classList.remove('hidden');
        }
        function pkRenderDate() {
            const D = PK.date; if (!D) return;
            const cur = D.inp.value, t = todayISO();
            let body = '';
            if (D.mode === 'y') {
                body = `<div class="pk-cal" style="grid-template-columns:repeat(4,1fr)">` + Array.from({ length: 16 }, (_, k) => D.y - 10 + k).map(y => `<span class="${y === +String(cur).slice(0, 4) ? 'on' : ''}" onclick="PK.date.y=${y}; PK.date.mode='m'; pkRenderDate()">${y}</span>`).join('') + `</div>`;
            } else if (D.mode === 'm') {
                body = `<div class="pk-cal" style="grid-template-columns:repeat(3,1fr)">` + OYLAR.map((n, k) => `<span class="${k === D.m ? 'on' : ''}" onclick="PK.date.m=${k}; PK.date.mode='d'; pkRenderDate()">${n}</span>`).join('') + `</div>`;
            } else {
                const first = new Date(D.y, D.m, 1), start = (first.getDay() + 6) % 7, days = new Date(D.y, D.m + 1, 0).getDate();
                let cells = ''; for (let k = 0; k < start; k++) cells += '<span class="o"></span>';
                for (let d = 1; d <= days; d++) { const iso = D.y + '-' + String(D.m + 1).padStart(2, '0') + '-' + String(d).padStart(2, '0'); cells += `<span class="${iso === cur ? 'on' : ''}${iso === t ? ' t' : ''}" onclick="pkSetDate('${iso}')">${d}</span>`; }
                body = `<div class="pk-cal">${['Du', 'Se', 'Ch', 'Pa', 'Ju', 'Sh', 'Ya'].map(x => '<i>' + x + '</i>').join('')}${cells}</div>`;
            }
            $id('pkDateBox').innerHTML = `<div class="pk-h"><b>${escapeHtml(pkLabelFor(D.inp))}</b><span onclick="pkClose()">✕</span></div>
                <div class="pk-cal-h"><button onclick="pkDateNav(-1)">‹</button><b onclick="PK.date.mode = PK.date.mode === 'd' ? 'y' : 'd'; pkRenderDate()">${D.mode === 'y' ? 'Yilni tanlang' : OYLAR[D.m] + ' ' + D.y} ▾</b><button onclick="pkDateNav(1)">›</button></div>${body}
                <div class="pk-btns"><button onclick="pkSetDate('')">Tozalash</button><button class="pr" onclick="pkSetDate(todayISO())">Bugun</button></div>`;
        }
        function pkDateNav(d) { const D = PK.date; if (D.mode === 'y') D.y += d * 16; else { D.m += d; if (D.m < 0) { D.m = 11; D.y--; } if (D.m > 11) { D.m = 0; D.y++; } } pkRenderDate(); }
        function pkSetDate(iso) {
            const inp = PK.date && PK.date.inp; if (!inp) return;
            const ch = inp.value !== iso; inp.value = iso; pkClose();
            if (ch) { inp.dispatchEvent(new Event('input', { bubbles: true })); inp.dispatchEvent(new Event('change', { bubbles: true })); }
        }
        // Tizim oynasi o'rniga ilovaning o'z oynasi (bosishda; surish/scroll buzilmaydi)
        (function () {
            let ts = null;
            const isSel = t => t && t.tagName === 'SELECT' && !t.multiple;
            const isDate = t => t && t.tagName === 'INPUT' && t.type === 'date';
            document.addEventListener('touchstart', e => { const t = e.target; if (isSel(t) || isDate(t)) ts = { t: t, x: e.touches[0].clientX, y: e.touches[0].clientY }; else ts = null; }, { passive: true, capture: true });
            document.addEventListener('touchend', e => {
                if (!ts) return; const t = ts.t, c = e.changedTouches[0]; const moved = Math.abs(c.clientX - ts.x) + Math.abs(c.clientY - ts.y) > 12; ts = null;
                if (moved || (e.target !== t && !t.contains(e.target))) return;
                e.preventDefault(); if (document.activeElement && document.activeElement.blur) document.activeElement.blur();
                if (isSel(t)) pkOpenSelect(t); else pkOpenDate(t);
            }, { passive: false, capture: true });
            document.addEventListener('mousedown', e => { const t = e.target; if (isSel(t) || isDate(t)) { e.preventDefault(); if (isSel(t)) pkOpenSelect(t); else pkOpenDate(t); } }, true);
            document.addEventListener('keydown', e => { const t = e.target; if ((isSel(t) || isDate(t)) && (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown')) { e.preventDefault(); if (isSel(t)) pkOpenSelect(t); else pkOpenDate(t); } }, true);
            document.addEventListener('click', e => { const t = e.target; if (isDate(t)) e.preventDefault(); }, true);
            // Chrome'ning avtoto'ldirish panelini o'chirish (parol maydonlaridan tashqari)
            const offAc = root => (root.querySelectorAll ? root.querySelectorAll('input:not([type=password]):not([autocomplete]), textarea:not([autocomplete])') : []).forEach(i => i.setAttribute('autocomplete', 'off'));
            offAc(document);
            try { new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(n => { if (n.nodeType === 1) { if ((n.tagName === 'INPUT' && n.type !== 'password') || n.tagName === 'TEXTAREA') { if (!n.hasAttribute('autocomplete')) n.setAttribute('autocomplete', 'off'); } else offAc(n); } }))).observe(document.body, { childList: true, subtree: true }); } catch (e) {}
        })();
        // Oddiy matn maydoniga to'q takliflar ro'yxati (datalist o'rniga)
        function sugAttach(inp, list) {
            if (!inp || inp.__sug) return; inp.__sug = true;
            const wrap = inp.parentElement; if (getComputedStyle(wrap).position === 'static') wrap.style.position = 'relative';
            const box = document.createElement('div'); box.className = 'sug-box hidden'; wrap.appendChild(box);
            const show = () => { const q = aiNorm(inp.value).trim(); const l = list().filter(s => !q || aiNorm(s).includes(q)).slice(0, 30);
                box.innerHTML = l.map(s => `<div>${escapeHtml(s)}</div>`).join(''); box.classList.toggle('hidden', !l.length);
                box.querySelectorAll('div').forEach((d, k) => d.addEventListener('mousedown', ev => { ev.preventDefault(); inp.value = l[k]; box.classList.add('hidden'); inp.dispatchEvent(new Event('input', { bubbles: true })); })); };
            inp.addEventListener('focus', show); inp.addEventListener('input', show); inp.addEventListener('blur', () => setTimeout(() => box.classList.add('hidden'), 150));
        }

        // ---------- 3) Xodim va lavozimni aqlli tanlash (butun ilova uchun yagona oyna) ----------
        const PP = { res: null, sel: null, role: '', opts: {} };
        function ppPeople() {
            const out = [], seen = new Set();
            (typeof allXodims === 'function' ? allXodims() : []).forEach(r => { const it = r.item; if (!it || !it.name) return; const k = normTxt(it.name); if (seen.has(k)) return; seen.add(k); out.push({ n: it.name, r: it.lavozim || '', t: cleanTabel(it.tabel || ''), src: 'x' }); });
            (typeof ndSigners === 'function' ? ndSigners() : []).forEach(s => { const k = normTxt(s.n); if (seen.has(k)) return; seen.add(k); out.push({ n: s.n, r: s.r, t: '', src: 's' }); });
            return out;
        }
        function ppRoles() {
            const set = new Map(); const add = s => { s = String(s || '').trim(); if (s && !set.has(normTxt(s))) set.set(normTxt(s), s); };
            try { (shtatTree.pos || []).forEach(p => add(p.name)); } catch (e) {}
            try { (shtatList || []).forEach(add); } catch (e) {}
            ppPeople().forEach(p => add(p.r));
            return Array.from(set.values());
        }
        function ppShort(full, lang) {
            const s = String(full || '').trim(); if (!s || /\.\s*\S/.test(s) && s.split(/\s+/).length <= 2) return s;
            const p = s.split(/\s+/).filter(w => !/^(o.g.li|qizi|ugli|kizi|угли|кизи)$/i.test(w));
            if (p.length < 2) return s;
            const ini = w => w ? w.charAt(0).toUpperCase() + '.' : '';
            return lang === 'ru' ? p[0] + ' ' + ini(p[1]) + ini(p[2]) : ini(p[1]) + p[0];
        }
        function pickPerson(o) {
            o = o || {};
            if (PR.res) { const r0 = PR.res; PR.res = null; r0(null); }
            if (PP.res) { const r1 = PP.res; PP.res = null; r1(null); }
            PP.opts = o; PP.sel = null; PP.role = o.r || '';
            return new Promise(res => {
                PP.res = res;
                $id('pkPersonBox').innerHTML = `<div class="pk-h"><b>👤 ${escapeHtml(o.title || 'Xodimni tanlash')}</b><span onclick="ppCancel()">✕</span></div>
                    <div class="pp-lbl">LAVOZIM (yozing — ro'yxat qisqaradi)</div>
                    <input class="pk-q" id="ppRole" placeholder="masalan: vagonlar bo'yicha muhandis" value="${escapeHtml(o.r || '')}" oninput="PP.role=this.value; ppRenderRoles(); ppRender()" onfocus="ppRenderRoles()" onblur="setTimeout(()=>{const e=$id('ppRoleList'); if(e) e.innerHTML=''},180)">
                    <div class="pp-rl" id="ppRoleList"></div>
                    <div class="pp-lbl">XODIM — tabel raqami, familiya yoki ism</div>
                    <input class="pk-q" id="ppQ" placeholder="2582 yoki @@N:389@@ yoki Sardor..." value="${escapeHtml(o.n || '')}" oninput="PP.sel=null; ppRender()">
                    <div id="ppSel"></div><div class="pp-cnt" id="ppCnt"></div><div class="pk-list" id="ppList"></div>
                    <div class="pk-btns"><button onclick="ppCancel()">Bekor qilish</button><button class="pr" onclick="ppOk()">💾 Saqlash</button></div>`;
                $id('pkPerson').classList.remove('hidden');
                ppRender();
                setTimeout(() => { const q = $id(o.r ? 'ppQ' : 'ppRole'); if (q) q.focus(); }, 120);
            });
        }
        function ppRenderRoles() {
            const el = $id('ppRoleList'); if (!el) return;
            if (document.activeElement !== $id('ppRole')) { el.innerHTML = ''; return; }
            const q = aiNorm($id('ppRole').value).trim(), toks = q.split(/\s+/).filter(Boolean);
            const l = ppRoles().filter(r => !toks.length || toks.every(t => aiNorm(r).includes(t))).slice(0, 40);
            el.innerHTML = l.map((r, k) => `<div class="pk-o" onmousedown="event.preventDefault()" onclick="ppSetRole(${k})"><span class="pk-t">${escapeHtml(r)}</span></div>`).join('');
            PP.roleList = l;
        }
        function ppSetRole(k) { const r = PP.roleList[k]; $id('ppRole').value = r; PP.role = r; $id('ppRoleList').innerHTML = ''; ppRender(); $id('ppQ').focus(); }
        function ppMatches() {
            const role = aiNorm($id('ppRole').value).trim(), q = aiNorm($id('ppQ').value).trim();
            const rt = role.split(/\s+/).filter(t => t.length > 1), qt = q.split(/\s+/).filter(Boolean);
            let l = ppPeople();
            if (rt.length) { const f = l.filter(p => rt.every(t => aiNorm(p.r).includes(t))); if (f.length || !qt.length) l = f; }
            if (qt.length) l = l.filter(p => qt.every(t => aiNorm(p.n).includes(t) || (p.t && p.t.startsWith(t))));
            const hint = aiNorm(PP.opts.hint || '');
            return l.sort((a, b) => (hint && aiNorm(b.r).includes(hint) ? 1 : 0) - (hint && aiNorm(a.r).includes(hint) ? 1 : 0) || a.n.localeCompare(b.n));
        }
        function ppRender() {
            const l = ppMatches();
            PP.list = l;
            $id('ppSel').innerHTML = PP.sel ? `<div class="pp-sel"><div>✅ <b>${escapeHtml(PP.sel.n)}</b><br><small>${escapeHtml(PP.sel.r)}${PP.sel.t ? ' · tabel ' + escapeHtml(PP.sel.t) : ''}</small></div><span onclick="PP.sel=null; ppRender()">✕</span></div>` : '';
            $id('ppCnt').innerText = l.length + ' ta xodim' + (l.length > 40 ? ' (40 tasi ko\'rsatilmoqda — ism yoki tabel yozib qisqartiring)' : '');
            $id('ppList').innerHTML = l.slice(0, 40).map((p, k) => `<div class="pk-o${PP.sel === p ? ' on' : ''}" onclick="ppChoose(${k})"><span class="pk-t">${p.src === 's' ? '⭐ ' : ''}${escapeHtml(p.n)}<small>${escapeHtml(p.r || '—')}${p.t ? ' · tabel ' + escapeHtml(p.t) : ''}</small></span></div>`).join('') || '<div class="pk-o dis">Bazadan topilmadi — yozganingiz qo\'lda saqlanadi</div>';
        }
        function ppChoose(k) { const p = PP.list[k]; if (!p) return; PP.sel = p; if (p.r) $id('ppRole').value = p.r; $id('ppQ').value = p.n; ppRender(); }
        function ppCancel() { if (PR.res) { prDone(null); return; } $id('pkPerson').classList.add('hidden'); const r = PP.res; PP.res = null; if (r) r(null); }
        function ppOk() {
            const role = $id('ppRole').value.trim(), name = (PP.sel ? PP.sel.n : $id('ppQ').value).trim();
            if (!name) { alert('Xodimni tanlang yoki F.I.Sh. yozing.'); return; }
            if (!role && PP.opts.needRole !== false) { alert('Lavozimni kiriting yoki tanlang.'); return; }
            $id('pkPerson').classList.add('hidden'); const r = PP.res; PP.res = null;
            if (r) r({ r: role, n: name, full: name, t: PP.sel ? PP.sel.t : '', short: ppShort(name, PP.opts.lang || 'uz') });
        }
        // Akt uchun: lavozim + qisqa F.I.Sh.
        async function ndPickSigner(pre, title) {
            const lang = ND_TYPES[ND.form.tur].l;
            const p = await pickPerson({ title: title || (pre ? "Imzo chekuvchini tahrirlash" : "Imzo chekuvchi qo'shish"), r: pre ? pre.r : '', n: pre ? pre.n : '', lang: lang });
            return p ? { r: p.r, n: p.short, t: p.t || '' } : null;
        }
        async function ndComEdit(k) { ndFormSync(); const c = ND.form.com[k]; if (!c) return; const p = await ndPickSigner(c); if (!p) return; ND.form.com[k] = p; ndRender(); }
        async function ndPickAp() { ndFormSync(); const p = await ndPickSigner(ND.form.apObj, 'Tasdiqlovchini tanlash'); if (!p) return; ND.form.apObj = p; ndRender(); }
        function ndApSet(i) { ndFormSync(); const s = ndSigners()[i]; if (s) ND.form.apObj = { r: s.r, n: s.n }; ndRender(); }
        function ndDefApObj() { const i = ndDefAp(); const s = ndSigners()[i]; return s ? { r: s.r, n: s.n } : null; }
        // Akt ko'rinishida qidiruv qatori yashiriladi — AI tugmasi o'ng pastga (suzuvchi) o'tadi
        function ndAiPos(solo) {
            const scr = $id('screen-nd'); if (!scr) return; const b = scr.querySelector('.ai-auto'); if (!b) return;
            const row = scr.querySelector('.ai-row');
            if (solo) { if (b.parentElement !== scr) scr.appendChild(b); b.classList.add('ai-float'); }
            else if (row) { b.classList.remove('ai-float'); if (b.parentElement !== row) row.appendChild(b); }
        }
        // Imzo chekuvchilar ro'yxati (sozlama): qo'shish va tahrirlash — aqlli tanlash orqali
        async function ndSignPick() {
            const l = ($id('ndSL') || {}).value || 'uz';
            const p = await pickPerson({ title: "Imzo chekuvchi qo'shish", r: $id('ndSR').value, n: $id('ndSN').value, lang: l });
            if (p) { $id('ndSR').value = p.r; $id('ndSN').value = p.short; }
        }
        async function ndEditSigner(i) {
            const s = ndSigners(), x = s[i]; if (!x) return;
            const p = await pickPerson({ title: 'Imzo chekuvchini tahrirlash', r: x.r, n: x.n, lang: x.l });
            if (!p) return; x.r = p.r; x.n = p.short; ndSet(ND_SIGN_KEY, s); ndRender();
        }
        async function hrPickMash() {
            const inp = $id('hrTMash'); if (!inp) return;
            const p = await pickPerson({ title: 'Mashinistni tanlash', n: inp.value, hint: 'mashinist', needRole: false });
            if (p) inp.value = p.n;
        }
        // Faqat lavozim tanlash (masalan, ish tarixida)
        const PR = { res: null, list: [], shtatOnly: false };
        function pickRole(o) {
            o = o || {};
            return new Promise(res => {
                if (PP.res) { const r0 = PP.res; PP.res = null; r0(null); }
                PR.res = res; PR.shtatOnly = !!o.shtatOnly;
                $id('pkPersonBox').innerHTML = `<div class="pk-h"><b>💼 ${escapeHtml(o.title || 'Lavozimni tanlash')}</b><span onclick="prDone(null)">✕</span></div>
                    <div class="pp-lbl">LAVOZIM (yozing — ro'yxat qisqaradi)</div>
                    <input class="pk-q" id="prQ" placeholder="masalan: muhandis" value="${escapeHtml(o.v || '')}" oninput="prRender()">
                    <div class="pp-cnt" id="prCnt"></div><div class="pk-list" id="prList"></div>
                    <div class="pk-btns"><button onclick="prDone(null)">Bekor qilish</button><button class="pr" onclick="prDone($id('prQ').value.trim())">💾 Saqlash</button></div>`;
                $id('pkPerson').classList.remove('hidden');
                prRender();
                setTimeout(() => { const q = $id('prQ'); if (q) q.focus(); }, 120);
            });
        }
        function prRoles() {
            if (!PR.shtatOnly) return ppRoles();
            const set = new Map(); const add = s => { s = String(s || '').trim(); if (s && !set.has(normTxt(s))) set.set(normTxt(s), s); };
            try { (shtatList || []).forEach(add); } catch (e) {}
            try { (shtatTree.pos || []).forEach(p => add(p.name)); } catch (e) {}
            return Array.from(set.values());
        }
        function prRender() {
            const q = aiNorm($id('prQ').value).trim(), toks = q.split(/\s+/).filter(Boolean);
            const l = prRoles().filter(r => !toks.length || toks.every(t => aiNorm(r).includes(t)));
            PR.list = l.slice(0, 60);
            $id('prCnt').innerText = l.length + ' ta lavozim' + (l.length > 60 ? ' (60 tasi ko\'rsatilmoqda)' : '');
            $id('prList').innerHTML = PR.list.map((r, k) => `<div class="pk-o" onclick="prDone(PR.list[${k}])"><span class="pk-t">${escapeHtml(r)}</span></div>`).join('') || '<div class="pk-o dis">Topilmadi — yozganingiz saqlanadi</div>';
        }
