        // AI: ehtiyot qismlar bo'yicha
        function spAiReply(q) {
            const partRe = /vtulka|valik|bolt|gayka|shayba|shplint|manjeta|silindr|shveller|ugolok|kolodka|rukav|elektrod|втулк|валик|болт|гайк|шайб|шплинт|манжет|швеллер|уголок|колодк|электрод/;
            if (!(/ehtiyot|zapchast|запчаст|zayavka|заявк/.test(q) || (partRe.test(q) && /nechta|necha|qancha|kerak|meyor|norma|сколько|норм/.test(q)))) return null;
            const nm = q.match(/(\d+)\s*(ta|dona)?\s*(dumpkar|vagon)/); const n = nm ? +nm[1] : 1;
            if (/zayavka|заявк/.test(q)) { setTimeout(() => { $id('aiChatModal').classList.add('hidden'); openSP('vag'); SP.view = 'list'; SP.set = 'y2027'; SP.n = n; spRender(); }, 700); return "🧮 " + n + " ta dumpkar KR uchun zayavka oynasi ochilmoqda — «🖨 Zayavka / PDF» tugmasini bosing."; }
            const TR = { vtulka: 'втулк', valik: 'валик', bolt: 'болт', gayka: 'гайк', shayba: 'шайб', shplint: 'шплинт', manjeta: 'манжет', silindr: 'цилиндр', shveller: 'швеллер', ugolok: 'уголок', list: 'лист', kolodka: 'колодк', rukav: 'рукав', truba: 'труба', elektrod: 'электрод' };
            const keys = Object.keys(TR).filter(k => q.includes(k)).map(k => TR[k]).concat((q.match(/[а-яё]{4,}/g) || []).map(w => w.slice(0, 5)));
            const sizes = q.match(/[mмøδ]\s?\d+/gi) || [];
            const l = spItems('y2027').filter(x => { const t = aiNorm(x.n); return (!keys.length || keys.some(k => t.includes(k))) && sizes.every(s => t.replace(/\s/g, '').includes(aiNorm(s).replace(/\s/g, '').replace('m', 'м'))); });
            if (!keys.length && !sizes.length) return "🔩 Ehtiyot qismlar bazasi: 2ВС-105 dumpkar KR me'yori (2027: " + spItems('y2027').length + " pozitsiya, 2024 va 2022 yillar bilan). Masalan so'rang: «vtulka nechta kerak», «5 ta dumpkar uchun bolt M20», «10 ta dumpkar zayavka».";
            if (!l.length) return "Kechirasiz, 2ВС-105 KR me'yoridan mos pozitsiya topilmadi.";
            return "🔩 2ВС-105 KR me'yori (2027)" + (n > 1 ? ', ' + n + ' ta vagon uchun' : ', 1 ta vagon uchun') + ":\n" + l.slice(0, 15).map(x => '• ' + x.n + ' — ' + spMul(x.q, n) + ' ' + x.u).join('\n') + (l.length > 15 ? '\n... va yana ' + (l.length - 15) + ' ta' : '');
        }

